package com.example.inventory;
import com.example.inventory.models.*;import com.example.inventory.services.InventoryService;import org.junit.jupiter.api.*;import java.sql.*;import static org.junit.jupiter.api.Assertions.*;
class InventoryServiceTest{Connection c;InventoryService s;@BeforeEach void setup()throws Exception{c=DriverManager.getConnection("jdbc:sqlite::memory:");for(String x:new String[]{"CREATE TABLE vendors(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,contact_info TEXT)","CREATE TABLE items(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>=0),vendor_id INTEGER)","CREATE TABLE stock_entries(id INTEGER PRIMARY KEY AUTOINCREMENT,item_id INTEGER,quantity INTEGER,type TEXT)"})c.createStatement().execute(x);s=new InventoryService(c);}@AfterEach void close()throws Exception{s.close();}@Test void addRead()throws Exception{Item i=new Item(0,"Keyboard",10,0);s.addItem(i);assertTrue(i.getId()>0);assertEquals("Keyboard",s.getItemById(i.getId()).getName());}@Test void stockFlow()throws Exception{Item i=new Item(0,"Mouse",10,0);s.addItem(i);s.adjustStock(i.getId(),5,"IN");assertEquals(15,s.getItemById(i.getId()).getQuantity());s.adjustStock(i.getId(),4,"OUT");assertEquals(11,s.getItemById(i.getId()).getQuantity());}@Test void preventsNegative()throws Exception{Item i=new Item(0,"Monitor",2,0);s.addItem(i);assertThrows(IllegalArgumentException.class,()->s.adjustStock(i.getId(),3,"OUT"));assertEquals(2,s.getItemById(i.getId()).getQuantity());}@Test void lowStock()throws Exception{s.addItem(new Item(0,"Cable",5,0));s.addItem(new Item(0,"Dock",8,0));assertEquals(1,s.getLowStockItems(5).size());}}